import{_ as r,o as t,c as e,a2 as o}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"인물 카드 계약","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-Profile-Contract.md","filePath":"world/Cast-Profile-Contract.md"}'),l={name:"world/Cast-Profile-Contract.md"};function n(s,a,i,d,c,h){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="인물-카드-계약" tabindex="-1">인물 카드 계약 <a class="header-anchor" href="#인물-카드-계약" aria-label="Permalink to &quot;인물 카드 계약&quot;">​</a></h1><p>이름 있는 인물을 새로 쓰거나 고칠 때는 아래 칸을 채운다. 칸이 비면 총람에 올리지 않는다. 국가별 명부의 정치 칸(성격, 야망, 공포, 통치, 관계, 촉발)은 그대로 두고, 그 앞에 출신·언어·징집·무장 접근을 붙인다.</p><p>422명을 한 번에 다시 쓰지 않는다. 새 인물과, 손을 대는 인물부터 이 계약을 적용한다.</p><h2 id="앞에-붙이는-칸" tabindex="-1">앞에 붙이는 칸 <a class="header-anchor" href="#앞에-붙이는-칸" aria-label="Permalink to &quot;앞에 붙이는 칸&quot;">​</a></h2><ul><li><strong>성명</strong>: 공개 이름. 한글과, 필요하면 로마자·본명. 예명만 쓰면 본명을 숨긴 이유를 적는다.</li><li><strong>출신 공동체</strong>: 붕괴 전 거주지, 국적, 체류 자격의 잔존 이름. 「한국인」한 줄로 끝내지 않는다.</li><li><strong>언어</strong>: 일상어, 시장에서 쓰는 말, 못 하는 말.</li><li><strong>생업</strong>: <a href="/world/Characters-Factions-and-Professions.html">생업 일곱</a> 중 하나. 겸직이면 주와 부를 나눈다. <code>근위</code>·<code>돌격</code>·<code>궁수</code>는 쓰지 않는다.</li><li><strong>소속</strong>: 16국, 잔존 군사, 이주민 회랑, 무소속 가운데 어느 장부에 이름이 있는지.</li><li><strong>직위</strong>: 그 장부에서 실제로 서명하는 일.</li><li><strong>징집 이력</strong>: 없음, 병·부사관, 예비군 명부, 동원 거부, 외국 군적. 붕괴 전 한국은 징병제다. 성인 남성이 사격을 안다는 말은 이 칸을 대신하지 못한다. 「해당 없음」도 이력이다.</li><li><strong>무장 접근</strong>: <a href="/world/Era-Arms-and-Tech-Level.html">무구 네 층</a> 중 어디에 손이 닿는지. 제식 소화기는 모델명 없이 「제식 소화기」로 적는다. 떠돌이에게 소총을 기본으로 주지 않는다.</li></ul><h2 id="정치-칸-기존-명부와-같음" tabindex="-1">정치 칸 (기존 명부와 같음) <a class="header-anchor" href="#정치-칸-기존-명부와-같음" aria-label="Permalink to &quot;정치 칸 (기존 명부와 같음)&quot;">​</a></h2><p>성격은 한 장면으로 읽히는 버릇. 야망은 지금 직위에서 이루려는 상태. 공포는 피하려는 결과. 통치·교섭은 거절과 서명을 어떻게 하는지. 핵심 관계는 친족·사제·지휘·계약·협력·원한 가운데 의미 있는 것만. 촉발 사건은 이 사람이 움직이면 세계 장부에 남는 일.</p><p>부상, 비밀, 얼굴, 휴대품은 아트나 전투가 필요할 때만 적는다. 휴대품은 생업 도구이거나 제식이다.</p><h2 id="이름" tabindex="-1">이름 <a class="header-anchor" href="#이름" aria-label="Permalink to &quot;이름&quot;">​</a></h2><p>한글 성명은 <a href="/world/Heirs-Names-and-World-Ledger.html">후계, 이름 로스터, 세계 원장</a>의 풀을 쓴다. 이주민 이름은 그 공동체에서 불리는 표기를 앞에 두고, 장부용 한글 음차를 옆에 둔다. 로마자만 있으면 언어 칸에 한글 장부가 없다고 적는다.</p><p>실존 공인 이름, 원작 고유명, 한 국가를 한 민족으로만 채우는 명단은 올리지 않는다.</p><h2 id="올릴-때" tabindex="-1">올릴 때 <a class="header-anchor" href="#올릴-때" aria-label="Permalink to &quot;올릴 때&quot;">​</a></h2><p>한 회랑 초안에 외국 출신이 한 명도 없으면 그 초안은 미완이다. 무장 접근이 생업과 어긋나면 안 된다. 상인은 기본적으로 싸우지 않는다.</p>',13)])])}const _=r(l,[["render",n]]);export{f as __pageData,_ as default};
